package tn.esprit.partnerintelligence.service;import org.springframework.stereotype.Service;import tn.esprit.partnerintelligence.entity.PromptTemplateVersion;import tn.esprit.partnerintelligence.repository.PromptTemplateVersionRepository;@Service public class PromptRegistryService{ private final PromptTemplateVersionRepository repo; public PromptRegistryService(PromptTemplateVersionRepository repo){this.repo=repo;} public String resolve(String key){ return repo.findFirstByPromptKeyAndActiveTrueOrderByCreatedAtDesc(key).map(PromptTemplateVersion::getTemplateText).orElse("Generate concise business recommendations in English."); }}